const int kRed4096PngLen = 58870;
//@RED1024_END@

// QQuickImageBase::Status values, read through the meta-property so the test
// does not depend on private QtQuick headers.
enum ImageStatus {
    StatusNull = 0,
    StatusReady = 1,
    StatusLoading = 2,
    StatusError = 3,
};

const char kModuleUri[] = "Seriona";

QString writeFixture(QTemporaryDir &dir, const char *name, const unsigned char *bytes, int length)
{
    QFile file(dir.filePath(QString::fromLatin1(name)));
    if (!file.open(QIODevice::WriteOnly)) {
        return {};
    }
    file.write(reinterpret_cast<const char *>(bytes), length);
    file.close();
    return dir.filePath(QString::fromLatin1(name));
}

seriona::control::PlayerStateSnapshot makeArtworkSnapshot(
    const QString &preferred, const QString &thumbnail)
{
    seriona::control::PlayerStateSnapshot snapshot;
    snapshot.playback.state = seriona::control::PlaybackStatus::Playing;
    snapshot.currentTrack = seriona::control::TrackIdentity{};
    snapshot.currentTrack->trackId = "track-art";
    snapshot.artwork = seriona::control::ArtworkRef{
        .localPath = std::filesystem::path(preferred.toStdString()),
        .thumbnailPath = std::filesystem::path(thumbnail.toStdString()),
    };
    return snapshot;
}

Seriona::App::GradientPalette samplePalette()
{
    return Seriona::App::GradientPalette{
        QStringLiteral("#aabbcc"), QStringLiteral("#bbccdd"), QStringLiteral("#ccddee")};
}

